    /// <summary>Name of a sensed ECL variable index, or null if out of range.</summary>
    public static string? EclVariableName(int index) =>
        index >= 0 && index < EclVariableNames.Length ? EclVariableNames[index] : null;

    /// <summary>CAS message for an index, or null if out of range.</summary>
    public static A220CasMessage? CasMessage(int index) =>
        index >= 0 && index < CasMessages.Length ? CasMessages[index] : null;
